/**
 * Cloudflare Bindings Types
 * Inline type definitions for Cloudflare Workers
 */

// Replicate the essential types from worker-configuration.d.ts
// The actual types are auto-generated by wrangler

interface KVNamespace {
  get(key: string, options?: { type?: "text" }): Promise<string | null>;
  get(key: string, options: { type: "json" }): Promise<unknown>;
  put(key: string, value: string | ReadableStream | ArrayBuffer, options?: { expirationTtl?: number }): Promise<void>;
  delete(key: string): Promise<void>;
}

interface SendEmail {
  send(options: {
    from: string;
    to: string;
    subject: string;
    html: string;
  }): Promise<void>;
}

interface Fetcher {
  fetch(request: Request | string, init?: RequestInit): Promise<Response>;
}

interface CloudflareBindings {
  OAUTH_STATE: KVNamespace;
  CF_EMAIL: SendEmail;
  ASSETS: Fetcher;
  NODE_ENV: string;
  // Add other bindings as needed
}

export type { CloudflareBindings };
